package ama.api;
import ama.contract.IdentityContracts.*;import ama.identity.SessionPort;import java.util.*;import java.time.Instant;import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;import org.springframework.mock.env.MockEnvironment;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
/** Cache policy only: inherited authentication/Origin/CSRF denials retain their original status. */
class Task11PublicationSecurityTest {
 @Test void finalAndPublicationAuthenticationDenialsArePrivateNoStore()throws Exception {for(String suffix:List.of("publication-destinations/libraries","final-confirmations/current","publications/current","publications/12345678-1234-4234-8234-123456789abd/zero-effect-retries","minutes","transcript")){var sessions=mock(SessionPort.class);when(sessions.resolve(null)).thenReturn(Optional.empty());var filter=new SessionSecurityFilter(sessions,new MockEnvironment().withProperty("local.server.port","8080"));var request=new MockHttpServletRequest("GET","/api/v1/meetings/12345678-1234-4234-8234-123456789abc/"+suffix);request.setLocalPort(8080);var response=new MockHttpServletResponse();var chain=new MockFilterChain();filter.doFilter(request,response,chain);assertEquals(401,response.getStatus());assertEquals("private, no-store",response.getHeader("Cache-Control"),suffix);assertNull(chain.getRequest());}}
 @Test void finalAndPublicationCsrfDenialsRemain403AndPrivate()throws Exception {for(String suffix:List.of("final-confirmations","publications","publications/12345678-1234-4234-8234-123456789abd/zero-effect-retries","minutes/generations")){var sessions=mock(SessionPort.class);String token="A".repeat(43);when(sessions.resolve(token)).thenReturn(Optional.of(new ResolvedSession(new Actor("owner",Status.ACTIVE,Set.of(Role.USER)),"B".repeat(43),Instant.now().plusSeconds(60))));var filter=new SessionSecurityFilter(sessions,new MockEnvironment().withProperty("local.server.port","8080").withProperty("identity.allowed-origin","https://b1.example.invalid"));var request=new MockHttpServletRequest("POST","/api/v1/meetings/12345678-1234-4234-8234-123456789abc/"+suffix);request.setLocalPort(8080);request.setCookies(new jakarta.servlet.http.Cookie(SessionCookies.NAME,token));request.addHeader("Origin","https://b1.example.invalid");var response=new MockHttpServletResponse();var chain=new MockFilterChain();filter.doFilter(request,response,chain);assertEquals(403,response.getStatus());assertEquals("private, no-store",response.getHeader("Cache-Control"),suffix);assertNull(chain.getRequest());}}
}
